# Homebrew formula for the paxel/tap tap — generated by the release workflow,
# which fills in the tagged version and the sha256 of each release tarball and
# pushes the result to the homebrew-tap repository as Formula/dedup.rb.
# Binary formula: it installs the prebuilt `dedup`.
class Dedup < Formula
  desc "Forensic data-inheritance triage: dedupe, diff and browse file piles"
  homepage "https://github.com/paxel/dedup-rs"
  version "3.0.0"
  license "MIT"

  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/paxel/dedup-rs/releases/download/v3.0.0/dedup-3.0.0-macos-arm64.tar.gz"
      sha256 "c232af2dd5fa9e3693a12e7e0ad9424a221d118e93e50f79b958e13f8a9cd2ef"
    else
      url "https://github.com/paxel/dedup-rs/releases/download/v3.0.0/dedup-3.0.0-macos-x86_64.tar.gz"
      sha256 "1395453f202616d1da57ea7ed0f9919ac771f5aff25315b963efff7af24364de"
    end
  end

  on_linux do
    url "https://github.com/paxel/dedup-rs/releases/download/v3.0.0/dedup-3.0.0-linux-x86_64.tar.gz"
    sha256 "bdc1d529a89dc553e7dd8726e2e7b8d482064f5bc5aa9089b7b55e69493d4817"
  end

  def install
    bin.install "dedup"
  end

  def caveats
    <<~EOS
      Optional tools unlock extra features (the app works without them):
        ffmpeg       — video previews, filmstrips, soundtrack playback
        poppler      — PDF page rendering (Render tab)
        libreoffice  — office/legacy document page rendering
    EOS
  end

  test do
    system "#{bin}/dedup", "--help"
  end
end
